export const catalog = [
 { id:'indoor-e30', name:'Indoor Cam E30', category:'Indoor security camera', price:'$199.95', image:'https://cdn.shopify.com/s/files/1/0737/0027/8551/files/1200_1200_9587a6ca-87f4-4c7d-8523-9f9fdffa6aa6.png?v=1738923381', url:'https://www.eufy.com/au/products/indoor-cam-e30?variant=51775675367791', description:'Indoor camera for your Living Room. Open its illustrated camera preview or review viewer access.', kind:'camera' },
 { id:'omni-c28', name:'eufy Omni C28 Robot Vacuum (White) and Mop with Dust Bag', category:'Robot vacuum & mop', price:'$1,229.99', image:'https://cdn.shopify.com/s/files/1/0737/0027/8551/files/BUNDLE-T211A210-1-T29YQA20-1_b5a2ccef-8c07-4cc2-8315-9c77880cadb9.png?v=1784001346', url:'https://www.eufy.com/au/products/bundle-t211ac20-1-t29yqa20-1?variant=53205557608815', description:'White robot vacuum and mop with its docking station and dust bag, matching the supplied product reference.', kind:'vacuum' }
];
export function productCards(){return `<section class="catalog-section"><div class="catalog-heading"><h2>Your selected products</h2><p>From your product references</p></div><div class="catalog-grid">${catalog.map(p=>`<article class="catalog-card"><a href="#product/${p.id}" class="catalog-image"><img src="${p.image}" alt="${p.name}" loading="lazy"></a><div class="catalog-copy"><p class="catalog-category">${p.category}</p><h3><a href="#product/${p.id}">${p.name}</a></h3><strong class="catalog-price">${p.price}</strong><small>Reference price from supplied screenshot</small><a class="eufy-primary" href="#product/${p.id}">View Product</a></div></article>`).join('')}</div></section>`;}
export function productView(app,id){const p=catalog.find(p=>p.id===id)||catalog[0];app.className='native-page product-page';document.title=`eufy · ${p.name}`;app.innerHTML=`<div class="page-heading"><a href="#shop" aria-label="Back to Shop">‹</a><h1>Product Details</h1></div><section class="product-detail"><div class="product-main-image"><img src="${p.image}" alt="${p.name}"></div><div class="product-main-copy"><span class="catalog-category">${p.category}</span><h2>${p.name}</h2><strong class="catalog-price">${p.price}</strong><p class="reference-price">Reference price from your screenshot · Not a live offer</p><p class="product-description">${p.description}</p><div class="product-links">${p.kind==='camera'?'<a class="eufy-primary" href="#device/living-room">Open Camera</a><a class="eufy-secondary" href="#events/access">Access History</a>':'<span class="badge">Demo device · Docked</span>'}<a class="official-product" href="${p.url}" target="_blank" rel="noopener noreferrer">View official eufy product ↗</a></div></div></section>`;}
export function vacuumCard(){const p=catalog[1];return `<article class="device-card vacuum-card"><div class="device-card-heading"><div><h2>Omni C28</h2><p>Robot Vacuum (White) <span>· Demo device</span></p></div><span class="badge">Docked · Demo</span></div><a class="vacuum-image" href="#product/omni-c28" aria-label="Open Omni C28 product"><img src="${p.image}" alt="Omni C28 white robot vacuum, docking station and dust bag" loading="lazy"></a><div class="vacuum-footer"><span>Robot Vacuum & Mop</span><a class="eufy-secondary" href="#product/omni-c28">View Product</a></div></article>`;}
